@startuml
class InsuranceCompany {
  + CompanyName : string
  + RegistrationNumber : int
}

class Policy {
  + PolicyType : string
  + CoverageAmount : double
}

class Customer {
  + CustomerId : int
  + CustomerName : string
}

class Contract {
  + ContractId : int
  + SigningDate : date
  + Status : string
}

InsuranceCompany "1" -- "*" Policy
InsuranceCompany "1" -- "*" Customer
Customer "1" -- "*" Contract
Contract "*" -- "1" Policy
@enduml

